param([ValidateSet("Release","Diagnostic","DeepDebug")][string]$Profile="Diagnostic")
$ErrorActionPreference="Stop"
. "$PSScriptRoot/../tools/toolchain.ps1"
$distro=Get-PhantomWslDistro
$wslBuild="/tmp/phantom-ev3-$($Profile.ToLower())";$source=Get-PhantomWslPath ev3;$diagnostic=if($Profile -eq "Release"){"OFF"}else{"ON"};$deepDebug=if($Profile -eq "DeepDebug"){"ON"}else{"OFF"};$buildType=if($Profile -eq "DeepDebug"){"Debug"}else{"Release"}
wsl.exe -d $distro -- bash -lc "rm -rf '$wslBuild' && cmake -S '$source' -B '$wslBuild' -G Ninja -DCMAKE_BUILD_TYPE=$buildType -DPHANTOM_DIAGNOSTIC=$diagnostic -DPHANTOM_DEEP_DEBUG=$deepDebug && cmake --build '$wslBuild'"
if($LASTEXITCODE-ne 0){throw "EV3 host build failed"}
$out=Join-Path (Resolve-Path .) "build\ev3-host-$($Profile.ToLower())";New-Item -ItemType Directory -Force "$out\bin"|Out-Null
$configSource=if($Profile -in @("Diagnostic","DeepDebug")){"config\generated\ev3-network-only.generated.json"}else{"config\generated\ev3.generated.json"};$bundleSource=if($Profile -in @("Diagnostic","DeepDebug")){"config\generated\commissioning_bundle-network-only.generated.json"}else{"config\generated\commissioning_bundle.generated.json"}
$share="\\wsl.localhost\$distro\tmp\phantom-ev3-$($Profile.ToLower())";Copy-Item "$share\phantom-controller","$share\phantom-safety" "$out\bin" -Force;Copy-Item deploy\scripts\device-integration-test.py "$out\bin\phantom-device-integration-test" -Force;Copy-Item ev3\network\phantom_network.py "$out\bin\phantom-network" -Force;Copy-Item ev3\network\phantom_mdns.py "$out\bin\phantom-mdns" -Force;Copy-Item protocol\phantom_protocol.py "$out\bin\phantom_protocol.py" -Force;Copy-Item protocol\jcs.py "$out\bin\jcs.py" -Force;Copy-Item protocol\generated\ipc_layout.py "$out\bin\ipc_layout.py" -Force;Copy-Item protocol\wire_schema.yaml "$out\bin\wire_schema.yaml" -Force;Copy-Item protocol\semantics.yaml "$out\bin\semantics.yaml" -Force;Copy-Item $configSource "$out\config.generated.json" -Force;Copy-Item $bundleSource "$out\commissioning-bundle.generated.json" -Force;Copy-Item deploy\systemd "$out\systemd" -Recurse -Force;Copy-Item deploy\tmpfiles "$out\tmpfiles" -Recurse -Force
$bundleKey=if($Profile -in @("Diagnostic","DeepDebug")){'commissioning_bundle-network-only'}else{'commissioning_bundle'};$bundleHash=(Get-Content config\generated\config-manifest.json -Raw|ConvertFrom-Json).artifact_hashes.$bundleKey
$commit=(git rev-parse HEAD).Trim();$dirty=((git status --porcelain).Count -gt 0);$sourceHash=(python tools\source_hash.py ev3 protocol deploy).Trim();$protocolHash=(Get-Content protocol\generated\schema.sha256).Split()[0];$protocolSemanticsHash=(Get-Content protocol\generated\semantics.sha256).Split()[0];$protocolContractHash=(Get-Content protocol\generated\contract.sha256).Split()[0];$configHash=(Get-FileHash $configSource -Algorithm SHA256).Hash.ToLower();$toolchainLockHash=(Get-FileHash toolchains\ev3dev-stretch.lock.json -Algorithm SHA256).Hash.ToLower();$buildId=(python tools\build_identity.py --component EV3 --profile $Profile --source-tree-hash $sourceHash --protocol-contract-hash $protocolContractHash --component-config-hash $configHash --toolchain-or-package-lock-hash $toolchainLockHash).Trim();$manifest=[ordered]@{schema_version=5;build_identity_schema="PHANTOM-BUILD-V4";component="EV3";build_id=$buildId;git_commit=$commit;source_tree_hash=$sourceHash;worktree_dirty=$dirty;build_profile=$Profile;target="host-test-not-armel";protocol_version=1;protocol_schema_hash=$protocolHash;protocol_semantics_hash=$protocolSemanticsHash;protocol_contract_hash=$protocolContractHash;compiler="g++ via WSL Ubuntu";toolchain_or_package_lock_hash=$toolchainLockHash;config_hash=$configHash;commissioning_bundle_hash=$bundleHash;source_date_epoch_or_reproducible_epoch=0};$manifest|ConvertTo-Json|Set-Content "$out\build-manifest.json" -Encoding UTF8
$checksumLines=Get-ChildItem $out -Recurse -File|Where-Object Name -ne SHA256SUMS|ForEach-Object{"$((Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower())  $($_.FullName.Substring($out.Length+1).Replace('\','/'))"}
[System.IO.File]::WriteAllText((Join-Path $out "SHA256SUMS"),(($checksumLines -join "`n")+"`n"),[System.Text.Encoding]::ASCII)
Write-Output "EV3 $Profile host artifact: $out"
